export const THROAT_RADIUS = 0.8;
export const THROAT_Y = 0;          // envelope's throat ring sits at y = 0
export const ENVELOPE_HEIGHT = 6;   // lathe runs from throat (y=0) to crown (y=6)
export const BASKET_DROP = 2.5;     // basket top hangs this far below the throat
const BASKET_W = 1.6;
const BASKET_D = 1.6;
const BASKET_H = 1.2;
const ROPE_RADIUS = 0.03;

/**
 * Teardrop profile for the envelope:
 * radius THROAT_RADIUS at the bottom, max 3 at 60% height,
 * tapering to a near-point crown.
 */
function envelopeProfile() {
  const stops = [
    [0.00, THROAT_RADIUS],
    [0.15, 1.75],
    [0.30, 2.60],
    [0.45, 2.95],
    [0.60, 3.0],   // max radius at 60% height
    [0.75, 2.50],
    [0.90, 1.30],
    [1.00, 0.05],
  ];
  return stops.map(([t, r]) => new THREE.Vector2(r, t * ENVELOPE_HEIGHT));
}

function makeRope(top, bottom) {
  const dir = new THREE.Vector3().subVectors(bottom, top);
  const length = dir.length();
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(ROPE_RADIUS, ROPE_RADIUS, length, 8),
    new THREE.MeshStandardMaterial({ color: 0x5b4632, roughness: 0.9 })
  );
  // Cylinder is built along +Y centered at origin: move to midpoint and
  // orient its axis from `top` toward `bottom`.
  mesh.position.copy(top).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(
    new THREE.Vector3(0, 1, 0),
    dir.clone().normalize()
  );
  mesh.name = 'rope';
  mesh.userData = {
    kind: 'rope',
    length,
    top: top.toArray(),
    bottom: bottom.toArray(),
  };
  return mesh;
}

export function buildBalloon() {
  const root = new THREE.Group();
  root.name = 'hotAirBalloon';

  // Envelope (lathe over teardrop profile)
  const envelope = new THREE.Mesh(
    new THREE.LatheGeometry(envelopeProfile(), 48),
    new THREE.MeshStandardMaterial({ color: 0xe0492a, roughness: 0.55 })
  );
  envelope.name = 'envelope';
  root.add(envelope);

  // Crown cap closes the small opening at the top of the lathe
  const crown = new THREE.Mesh(
    new THREE.CircleGeometry(envelopeProfile().at(-1).x, 24),
    new THREE.MeshStandardMaterial({ color: 0xb93a20, roughness: 0.55, side: THREE.DoubleSide })
  );
  crown.rotation.x = -Math.PI / 2;
  crown.position.y = ENVELOPE_HEIGHT;
  crown.name = 'crown';
  root.add(crown);

  // Basket hanging below the throat
  const basketTopY = THROAT_Y - BASKET_DROP;
  const basket = new THREE.Mesh(
    new THREE.BoxGeometry(BASKET_W, BASKET_H, BASKET_D),
    new THREE.MeshStandardMaterial({ color: 0x8a5a2b, roughness: 0.85 })
  );
  basket.position.y = basketTopY - BASKET_H / 2;
  basket.name = 'basket';
  basket.userData.kind = 'basket';
  root.add(basket);

  // Exactly 4 ropes: basket top corners -> points on the throat ring.
  const corners = [
    new THREE.Vector3(BASKET_W / 2, basketTopY, BASKET_D / 2),
    new THREE.Vector3(-BASKET_W / 2, basketTopY, BASKET_D / 2),
    new THREE.Vector3(-BASKET_W / 2, basketTopY, -BASKET_D / 2),
    new THREE.Vector3(BASKET_W / 2, basketTopY, -BASKET_D / 2),
  ];
  for (const corner of corners) {
    const angle = Math.atan2(corner.z, corner.x); // same azimuth as the corner
    const ringPoint = new THREE.Vector3(
