result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/balloon.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildBalloon, bobBalloon, THROAT_RADIUS, THROAT_Y, BASKET_DROP, ENVELOPE_HEIGHT } from '../src/balloon.js';

const EPS = 1e-6;

function build() {
  const b = buildBalloon();
  const ropes = b.children.filter((c) => c.userData.kind === 'rope');
  const envelope = b.getObjectByName('envelope');
  const basket = b.getObjectByName('basket');
  return { b, ropes, envelope, basket };
}

/** Endpoints of a rope cylinder mesh expressed in the root's frame. */
function ropeEndpoints(rope) {
  const len = rope.geometry.parameters.height;
  const top = new THREE.Vector3(0, len / 2, 0)
    .applyQuaternion(rope.quaternion)
    .add(rope.position);
  const bottom = new THREE.Vector3(0, -len / 2, 0)
    .applyQuaternion(rope.quaternion)
    .add(rope.position);
  return { top, bottom };
}

describe('buildBalloon', () => {
  it('has exactly 4 ropes', () => {
    const { ropes } = build();
    expect(ropes.length).toBe(4);
  });

  it('each rope mesh length equals its endpoint distance within 1e-6', () => {
    const { ropes } = build();
    for (const rope of ropes) {
      rope.geometry.computeBoundingBox();
      const size = new THREE.Vector3();
      rope.geometry.boundingBox.getSize(size);
      const majorExtent = Math.max(size.x, size.y, size.z);

      const stored = rope.userData.length;
      const endpointDist = new THREE.Vector3()
        .subVectors(
          new THREE.Vector3().fromArray(rope.userData.bottom),
          new THREE.Vector3().fromArray(rope.userData.top)
        )
        .length();

      expect(Math.abs(majorExtent - endpointDist)).toBeLessThanOrEqual(EPS);
      expect(Math.abs(stored - endpointDist)).toBeLessThanOrEqual(EPS);
      expect(endpointDist).toBeGreaterThan(0);
    }
  });

  it('rope tops lie on the throat ring and bottoms at basket corners', () => {
    const { b, ropes } = build();

    // Basket corners in root space (basket is axis-aligned box).
    const basketSize = new THREE.Vector3();
    new THREE.Box3().setFromObject(basket).getSize(basketSize);
    const basketTopY = THROAT_Y - BASKET_DROP;
    const expectedCorners = [
      [basketSize.x / 2, basketTopY, basketSize.z / 2],
      [-basketSize.x / 2, basketTopY, basketSize.z / 2],
      [-basketSize.x / 2, basketTopY, -basketSize.z / 2],
      [basketSize.x / 2, basketTopY, -basketSize.z / 2],
    ];

    const usedCorners = new Set();
    for (const rope of ropes) {
      const { top, bottom } = ropeEndpoints(rope);

      // Top: on throat circle
      expect(Math.abs(top.y - THROAT_Y)).toBeLessThanOrEqual(EPS);
      const ringRadius = Math.hypot(top.x, top.z);
      expect(Math.abs(ringRadius - THROAT_RADIUS)).toBeLessThanOrEqual(EPS);

      // Bottom: one of the four basket top corners
      let matched = -1;
      expectedCorners.forEach(([x, y, z], i) => {
        if (
          Math.abs(bottom.x - x) <= EPS &&
          Math.abs(bottom.y - y) <= EPS &&
          Math.abs(bottom.z - z) <= EPS
        ) {
          matched = i;
        }
      });
      expect(matched).toBeGreaterThanOrEqual(0);
      expect(usedCorners.has(matched)).toBe(false); // each corner used once
      usedCorners.add(matched);

      // Stored metadata agrees with actual geometry
      expect(top.distanceTo(new THREE.Vector3().fromArray(rope.userData.top))).toBeLessThanOrEqual(EPS);
      expect(bottom.distanceTo(new THREE.Vector3().fromArray(rope.userData.bottom))).toBeLessThanOrEqual(EPS);
    }
    expect(usedCorners.size).toBe(4);
  });

  it('envelope Box3 max radius matches 3 within 5%', () => {
    const { envelope } = build();
    const size = new THREE.Vector3();
    new THREE.Box3().setFromObject(envelope).getSize(size);
    const maxRadius = Math.max(size.x, size.z) / 2;
    expect(maxRadius).toBeGreaterThan(3 * 0.95);
    expect(maxRadius).toBeLessThan(3 * 1.05);
    // sanity: full teardrop height
    expect(size.y).toBeCloseTo(ENVELOPE_HEIGHT, 5);
  });
});

describe('bobBalloon', () => {
  it('returns to y = 0 at t = PI/0.7 while rotation advanced', () => {
    const { b } = build();
    bobBalloon(b, 1.23); // arbitrary phase first
    const rotBefore = b.rotation.y;
    bobBalloon(b, Math.PI / 0.7);
    expect(Math.abs(b.position.y)).toBeLessThan(1e-9);
    expect(b.rotation.y).not.toBe(rotBefore);
    expect(b.rotation.y).toBeCloseTo((0.1 * Math.PI) / 0.7, 12);
  });
});

describe('serialization', () => {
  it('serializes and revives via ObjectLoader with same child count', () => {
    const { b } = build();
    const json = JSON.stringify(b.toJSON());
    const revived = new THREE.ObjectLoader().parse(JSON.parse(json));
    expect(revived.children.length).toBe(b.children.length);
    const revivedRopes = revived.children.filter((c) => c.userData.kind === 'rope');
    expect(revivedRopes.length).toBe(4);
    // geometry survives: rope lengths preserved
    for (const rope of revivedRopes) {
      expect(rope.geometry.parameters.height).toBeCloseTo(rope.userData.length, 10);
    }
  });
});
"})
